INSERT INTO `locaux` (`id`, `titre`, `adresse`, `sous_titre`, `description`, `surface`, `created_at`, `updated_at`, `image_path`, `slug`, `localisation`, `formId`, `longitude`, `latitude`, `desc_card`) VALUES
(1, 'Locaux Commerciaux Dar el Beida', 'Résidence Perla ', 'Des locaux à vendre et à louer  \r\n', 'Ne ratez pas cette opportunité exceptionnelle d\'acquérir un local de prestige, situé au niveau de la <strong>résidence Perla</strong>, dans la localité dynamique de <strong>Dar el Beida</strong>. <strong>Deux locaux de 97,3 m² et 124 m² sont disponibles à la location</strong>, soigneusement agencés et équipés de climatisation et de chauffage centralisés, de quoi assurer un confort optimal tout au long de l\'année. <br /> <br />\r\nLa localisation stratégique et la qualité de de finition intérieure en font l\'espace idéal pour établir votre entreprise ou votre activité. Situé dans un quartier calme, ces locaux offrent une visibilité accrue et un accès facile pour vos clients et partenaires d\'affaires. <strong>Ne manquez pas cette occasion de faire prospérer votre entreprise dans un environnement de qualité!</strong>', ' 97,3m² - 124m²', '2023-11-30 14:31:36', '2024-06-04 14:29:45', 'images/locaux/perla/4.jpg', 'locaux-commerciaux-dar-el-beida', '<iframe src=\"https://www.google.com/maps/embed?pb=!1m18!1m12!1m3!1d102308.61551140808!2d3.0093534981949124!3d36.74310885863456!2m3!1f0!2f0!3f0!3m2!1i1024!2i768!4f13.1!3m3!1m2!1s0x128e5156309178f7%3A0x81ac68e98d3b97c!2sR%C3%A9sidence%20Perla%20Aymen%20Promotion!5e0!3m2!1sfr!2sdz!4v1704877191922!5m2!1sfr!2sdz\" width=\"600\" height=\"450\" style=\"border:0;\" allowfullscreen=\"\" loading=\"lazy\" referrerpolicy=\"no-referrer-when-downgrade\"></iframe>', '336a375c-a864-4124-8c06-d19b4f50e78e', 3.20711, 36.7213, 'Lancez votre projet ambitieux en louant l’un de nos locaux commerciaux à Dar el Beïda, au niveau de notre résidence phare Perla.'),
(2, 'Locaux Commerciaux Dely Ibrahim\r\n', 'Résidence Béryl ', 'Des locaux à vendre et à louer \r\n', 'Vous êtes féru de sport et vous souhaitez créer un espace de remise en forme original ? nous avons l’espace idéal pour vous ! <br /> <br />\r\nAu sein de la localité vivante de <strong>Dély Ibrahim</strong>, située dans un quartier calme et prospère, se trouve la <strong>résidence Béryl</strong> qui dispose d’un vaste local d’une <strong>surface totale de 440 m²</strong>. L’espace est optimisé et dispose de diverses installations pour vous faciliter la vie, telles que le chauffage et la climatisation centralisés, en plus d’une visibilité certaine grâce à l’emplacement du local et de la résidence, une base de clients déjà existante et une zone de chalandise importante. ', '440 m²', '2023-11-30 14:35:49', '2024-06-04 14:29:26', 'images/locaux/beryl/14.jpg', 'locaux-commerciaux-beryl', '<iframe src=\"https://www.google.com/maps/embed?pb=!1m18!1m12!1m3!1d3196.4211313924357!2d2.982033975301116!3d36.76046346993935!2m3!1f0!2f0!3f0!3m2!1i1024!2i768!4f13.1!3m3!1m2!1s0x128fb140dda3f1e1%3A0xa6c4b440c3fcf89!2sR%C3%A9sidence%20B%C3%A9ryl%20-%20Aymen%20Promotion%20Immobili%C3%A8re!5e0!3m2!1sfr!2sdz!4v1704875092524!5m2!1sfr!2sdz\" width=\"600\" height=\"450\" style=\"border:0;\" allowfullscreen=\"\" loading=\"lazy\" referrerpolicy=\"no-referrer-when-downgrade\"></iframe>', '127c2a3c-ac6f-4afc-a67c-34d4c86d5fe0', 2.98459, 36.7607, 'Ne ratez pas notre vaste local commercial de 440 m² dans la commune de Dely Ibrahim, au sein de notre résidence haut standing Béryl.\n'),
(5, 'Locaux Commerciaux Les Sources\r\n', 'Résidence Spinelle', 'Des locaux à vendre et à louer  \r\n', 'Vous cherchez un espace commercial de choix dans un emplacement privilégié au cœur de la commune des <strong>Sources à Alger</strong> ? Nous avons ce qu\'il vous faut au niveau de la <strong>résidence Spinelle</strong> ! <strong>Deux superbes locaux commerciaux de 77,5 m² et 93,85 m²</strong> sont actuellement disponibles à la location, offrant une opportunité exceptionnelle pour lancer votre entreprise. <br /> <br />\r\nGrâce à son aménagement polyvalent permettant d\'adapter l\'espace à vos besoins, et son emplacement stratégique, vous bénéficierez d\'une visibilité optimale, attirant un flux constant de résidents et de visiteurs. Les Sources est un quartier vivant de la ville d’Alger, offrant un mélange dynamique de résidences, de commerces et d\'espaces de loisirs. <br /> <br />\r\nCes locaux commerciaux sont une opportunité rare de démarrer ou de développer votre activité dans un quartier en pleine croissance. ', '77,5 m² - 93,85 m²', '2023-11-30 14:38:32', '2024-06-04 14:29:02', 'images/locaux/spinelle/1.jpg', 'locaux-commerciaux-les-sources', '<iframe src=\"https://www.google.com/maps/embed?pb=!1m18!1m12!1m3!1d3197.487591359538!2d3.005334775299892!3d36.73486577138051!2m3!1f0!2f0!3f0!3m2!1i1024!2i768!4f13.1!3m3!1m2!1s0x128faf6906783591%3A0x5031396afe05cbcc!2sR%C3%A9sidence%20Opale%20-%20Aymen%20Promotion%20Immobili%C3%A8re!5e0!3m2!1sfr!2sdz!4v1704711462963!5m2!1sfr!2sdz\" width=\"600\" height=\"450\" style=\"border:0;\" allowfullscreen=\"\" loading=\"lazy\" referrerpolicy=\"no-referrer-when-downgrade\"></iframe>', '336a375c-a864-4124-8c06-d19b4f50e78e', 3.00913, 36.735, 'Découvrez nos deux locaux commerciaux situés au cœur de la commune des Sources au niveau de notre résidence Spinelle. \n'),
(7, 'Locaux commerciaux Les Sources', 'Résidence Turquoise', 'Des locaux à vendre et à louer  ', 'Dans la  <strong>commune des Sources </strong>, au sein de la  <strong>résidence Turquoise </strong>, nous mettons à votre disposition  <strong>deux spacieux locaux commerciaux </strong> qui se prêtent parfaitement au lancement d\'une nouvelle entreprise ou à l\'expansion de votre activité existante. Ces deux locaux, offrant respectivement  <strong>79 m² et 185 m² d\'espace </strong>, se distinguent par leur luminosité et leur atmosphère accueillante, prêts à être aménagés selon vos besoins. De plus, ils sont équipés de systèmes de climatisation et de chauffage centralisés pour votre confort. <br /> <br />', '79 m² - 185 m²', '2024-03-23 13:04:49', '2024-06-04 14:28:27', 'images/locaux/turquoise/turquoise-2.jpg', 'locaux-commerciaux-turquoise', '<iframe src=\"https://www.google.com/maps/embed?pb=!1m14!1m8!1m3!1d12789.999773908248!2d3.0575459!3d36.7345692!3m2!1i1024!2i768!4f13.1!3m3!1m2!1s0x128fad271494c921%3A0x7bcfde55e4d25c10!2sR%C3%A9sidence%20Turquoise%20-%20Aymen%20Promotion!5e0!3m2!1sen!2sdz!4v1712481908811!5m2!1sen!2sdz\" width=\"600\" height=\"450\" style=\"border:0;\" allowfullscreen=\"\" loading=\"lazy\" referrerpolicy=\"no-referrer-when-downgrade\"></iframe>', '718685b8-21a3-4cf1-9907-68bde7b2698b', 3.05782, 36.7347, 'Ne ratez pas nos deux locaux commerciaux au niveau de la résidence Turquoise, très bien situés dans la commune des Sources.');
